def strategy(history, rng):
    if not history:
        return 'C'

    def opp(idx):
        return history[idx][1]

    n = len(history)
    my_score = 0
    opp_score = 0
    for a, b in history:
        if a == 'C' and b == 'C':
            my_score += 3
            opp_score += 3
        elif a == 'C' and b == 'D':
            my_score += 0
            opp_score += 5
        elif a == 'D' and b == 'C':
            my_score += 5
            opp_score += 0
        else:
            my_score += 1
            opp_score += 1

    last_opp = opp(n - 1)
    opp_defections = sum(1 for i in range(n) if opp(i) == 'D')
    defection_rate = opp_defections / n

    recent_len = min(10, n)
    recent_defections = sum(1 for i in range(n - recent_len, n) if opp(i) == 'D')

    if my_score >= opp_score:
        if last_opp == 'D':
            if recent_defections >= 3:
                return 'D'
            if defection_rate > 0.35:
                return 'D'
            if rng.random() < 0.25:
                return 'D'
            return 'C'
        else:
            if defection_rate > 0.75:
                return 'D'
            return 'C'

    if last_opp == 'D':
        if recent_defections >= 2:
            return 'D'
        if defection_rate > 0.25:
            return 'D'
        if rng.random() < 0.6:
            return 'D'
        return 'C'

    if defection_rate > 0.6:
        return 'D'
    if defection_rate > 0.4 and rng.random() < 0.3:
        return 'D'

    return 'C'

